draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // wall
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.rect(W/2 + 50, 0, 20, H);
  ctx.stroke();

  // banging
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 80);
  ctx.lineTo(W/2 + 50, H/2 + 80 - 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
